// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        t1 = uint64(bound(t1, 1, type(uint64).max / 2));
        t2 = uint64(bound(t2, t1 + 1, type(uint64).max));

        vm.roll(1);
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        vm.roll(2);
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: any second call with a strictly larger timestamp succeeds.
        assertTrue(ok2 && ok1);
    }
}
